local SaddleSoapMaker = {}
local PRODUCTS = {
    iron_saddle_soap = { name = "Železno milo za sedla", ironCost = 1, woodCost = 2, leatherCost = 3, time = 5, cost = 130, prestige = 3, happiness = 2, description = "Železno milo za čiščenje sedel." },
    bronze_saddle_soap = { name = "Bronasto milo za sedla", bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 7, cost = 320, prestige = 5, happiness = 3, description = "Bronasto milo za negovana sedla." },
    silver_saddle_soap = { name = "Srebrno milo za sedla", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 11, cost = 780, prestige = 10, happiness = 4, description = "Srebrno milo za plemiška sedla." },
    gilded_saddle_soap = { name = "Pozlačeno milo za sedla", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 15, cost = 1700, prestige = 19, happiness = 5, description = "Pozlačeno milo za dvorna sedla." },
    jewel_set_saddle_soap = { name = "Draguljasto milo za sedla", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 19, cost = 3700, prestige = 35, happiness = 7, description = "Draguljasto milo za kraljevska sedla." },
    royal_sovereign_saddle_soap = { name = "Kraljevski suvereno milo za sedla", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 26, cost = 8000, prestige = 67, happiness = 13, description = "Suvereno milo z biseri za krono." },
}
local BUILDINGS = {
    saddlesoap_workshop = { name = "Milna delavnica", cost = { gold = 295, wood = 180, stone = 120, iron = 5 }, upkeep = 5, qualityBonus = 5 },
    saddlesoap_house = { name = "Milna hiša", cost = { gold = 1100, wood = 360, stone = 250, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_saddlesoap_atelier = { name = "Mojstrski milni atelje", cost = { gold = 2850, wood = 420, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_saddlesoap_palace = { name = "Suverena milna palača", cost = { gold = 12400, wood = 645, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
SaddleSoapMaker.ironStock = 8; SaddleSoapMaker.bronzeStock = 6; SaddleSoapMaker.woodStock = 16; SaddleSoapMaker.leatherStock = 18; SaddleSoapMaker.silverStock = 8; SaddleSoapMaker.goldStock = 6; SaddleSoapMaker.jewelStock = 4; SaddleSoapMaker.pearlStock = 4
SaddleSoapMaker.productStock = {}; SaddleSoapMaker.buildings = {}; SaddleSoapMaker.maker = nil; SaddleSoapMaker.activeMaking = {}; SaddleSoapMaker.totalProducts = 0; SaddleSoapMaker.dayTimer = 0
function SaddleSoapMaker.init() SaddleSoapMaker.ironStock=8; SaddleSoapMaker.bronzeStock=6; SaddleSoapMaker.woodStock=16; SaddleSoapMaker.leatherStock=18; SaddleSoapMaker.silverStock=8; SaddleSoapMaker.goldStock=6; SaddleSoapMaker.jewelStock=4; SaddleSoapMaker.pearlStock=4; SaddleSoapMaker.productStock={}; SaddleSoapMaker.buildings={}; SaddleSoapMaker.maker=nil; SaddleSoapMaker.activeMaking={}; SaddleSoapMaker.totalProducts=0; SaddleSoapMaker.dayTimer=0; print("[SaddleSoapMaker] Royal Saddle Soap Maker System initialized (6 products, 4 buildings)") end
function SaddleSoapMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaddleSoapMaker.maker={name=n or ("Milar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Milar najet: %s (spretnost: %d)",SaddleSoapMaker.maker.name,s),"success") end; return true end
function SaddleSoapMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaddleSoapMaker.build(id) local ok,e=SaddleSoapMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaddleSoapMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaddleSoapMaker.getQualityBonus() local b=0; for _,bd in ipairs(SaddleSoapMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaddleSoapMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SaddleSoapMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SaddleSoapMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SaddleSoapMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SaddleSoapMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SaddleSoapMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaddleSoapMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaddleSoapMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SaddleSoapMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SaddleSoapMaker.buildings==0 then return false,"Potrebna milna delavnica" end; if not SaddleSoapMaker.maker then return false,"Potreben milar" end; return true end
function SaddleSoapMaker.make(pt,qty) qty=qty or 1; local ok,e=SaddleSoapMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SaddleSoapMaker.ironStock=SaddleSoapMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SaddleSoapMaker.bronzeStock=SaddleSoapMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SaddleSoapMaker.woodStock=SaddleSoapMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SaddleSoapMaker.leatherStock=SaddleSoapMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SaddleSoapMaker.silverStock=SaddleSoapMaker.silverStock-d.silverCost*qty end; if d.goldCost then SaddleSoapMaker.goldStock=SaddleSoapMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SaddleSoapMaker.jewelStock=SaddleSoapMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SaddleSoapMaker.pearlStock=SaddleSoapMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SaddleSoapMaker.maker then t=math.max(1,t-math.floor(SaddleSoapMaker.maker.skill/13)) end; table.insert(SaddleSoapMaker.activeMaking,{id="saddlesoap_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaddleSoapMaker.completeMaking(m) local q=1.0+(SaddleSoapMaker.getQualityBonus()/100); if SaddleSoapMaker.maker then q=q+(SaddleSoapMaker.maker.skill/140) end; q=math.min(2.5,q); SaddleSoapMaker.productStock[m.productType]=(SaddleSoapMaker.productStock[m.productType] or 0)+m.quantity; SaddleSoapMaker.totalProducts=SaddleSoapMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaddleSoapMaker.maker then SaddleSoapMaker.maker.itemsMade=SaddleSoapMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SaddleSoapMaker.maker.skill=math.min(100,SaddleSoapMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Milo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saddlesoap.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SaddleSoapMaker.update(dt) if not _G.state then return end; SaddleSoapMaker.dayTimer=SaddleSoapMaker.dayTimer+dt; if SaddleSoapMaker.dayTimer>=30 then SaddleSoapMaker.dayTimer=0; for i=#SaddleSoapMaker.activeMaking,1,-1 do local m=SaddleSoapMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaddleSoapMaker.completeMaking(m); table.remove(SaddleSoapMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaddleSoapMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaddleSoapMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaddleSoapMaker.getStats() return {ironStock=SaddleSoapMaker.ironStock,bronzeStock=SaddleSoapMaker.bronzeStock,woodStock=SaddleSoapMaker.woodStock,leatherStock=SaddleSoapMaker.leatherStock,silverStock=SaddleSoapMaker.silverStock,goldStock=SaddleSoapMaker.goldStock,jewelStock=SaddleSoapMaker.jewelStock,pearlStock=SaddleSoapMaker.pearlStock,productStock=SaddleSoapMaker.productStock,numBuildings=#SaddleSoapMaker.buildings,hasMaker=SaddleSoapMaker.maker~=nil,makerName=SaddleSoapMaker.maker and SaddleSoapMaker.maker.name or "—",makerSkill=SaddleSoapMaker.maker and SaddleSoapMaker.maker.skill or 0,activeMaking=#SaddleSoapMaker.activeMaking,totalProducts=SaddleSoapMaker.totalProducts} end
return SaddleSoapMaker
